\set ON_ERROR_STOP on
begin;
do $$declare t uuid:='10000000-0000-4000-8000-000000000001';owner uuid:='00000000-0000-4000-8000-000000000001';reviewer uuid:='00000000-0000-4000-8000-000000000002';candidate uuid:='00000000-0000-4000-8000-000000000003';asset uuid;bank uuid;hotspot uuid;diagram uuid;payload jsonb;material jsonb;aid uuid;definition jsonb;did uuid;ver uuid;win uuid;reg uuid;form jsonb;reply jsonb;data jsonb;counts bigint;
begin
 select id into asset from public.assessment_artifacts where tenant_id=t and kind='image' and state='ready' limit 1;
 if asset is null then raise exception 'Existing canonical scanned image fixture missing';end if;
 select id into bank from public.assessment_item_banks where tenant_id=t limit 1;
 payload:=jsonb_build_object('schema_version','assessment.item.v1','type','hotspot','prompt','Select the reviewed target','locale','en','max_score',1,'tags','[]'::jsonb,'media',jsonb_build_array(jsonb_build_object('artifact_id',asset,'kind','image','alt','Reviewed public illustration')),'image_response',jsonb_build_object('schema_version','assessment.image-response.v1','artifact_id',asset));
 material:=jsonb_build_object('bank_id',bank,'item',payload,'key','{"hotspot":{"regions":[{"shape":"rectangle","x1":0.1,"y1":0.2,"x2":0.4,"y2":0.8}]},"case_sensitive":false,"partial_credit":false}'::jsonb);
 begin perform public.assessment_command(owner,t,'image-invalid-public-target','item.create',jsonb_set(material,'{item,image_response,regions}','[]'));raise exception 'Private target entered public payload';exception when check_violation then null;end;
 begin perform public.assessment_command(owner,t,'image-invalid-region','item.create',jsonb_set(material,'{key,hotspot,regions,0,x2}','0.05'));raise exception 'Reversed target rectangle accepted';exception when check_violation then null;end;
 begin perform public.assessment_command(owner,t,'image-invalid-polygon','item.create',jsonb_set(material,'{key,hotspot,regions,0}','{"shape":"polygon","points":[{"x":0,"y":0},{"x":1,"y":1},{"x":0,"y":1},{"x":1,"y":0}]}'));raise exception 'Self-intersecting polygon accepted';exception when check_violation then null;end;
 hotspot:=(public.assessment_command(owner,t,'image-create-hotspot','item.create',material)->>'id')::uuid;
 payload:=jsonb_set(payload,'{type}','"diagram_labeling"')||jsonb_build_object('response_ids',jsonb_build_array('label_1','label_2'),'image_response',jsonb_build_object('schema_version','assessment.image-response.v1','artifact_id',asset,'anchors',jsonb_build_array(jsonb_build_object('response_id','label_1','x',.2,'y',.3),jsonb_build_object('response_id','label_2','x',.8,'y',.7))));
 material:=jsonb_build_object('bank_id',bank,'item',payload,'key','{"correct":{"label_1":["Cat","Feline"],"label_2":["Dog"]},"case_sensitive":false,"partial_credit":true}'::jsonb);
 begin perform public.assessment_command(owner,t,'image-invalid-anchor','item.create',jsonb_set(material,'{item,image_response,anchors,1,response_id}','"label_1"'));raise exception 'Duplicate public anchor accepted';exception when check_violation then null;end;
 begin perform public.assessment_command(owner,t,'image-invalid-label-key','item.create',jsonb_set(material,'{key,correct}','{"label_1":["Cat"],"foreign_label":["Dog"]}'));raise exception 'Foreign private diagram key label accepted';exception when check_violation then null;end;
 diagram:=(public.assessment_command(owner,t,'image-create-diagram','item.create',material)->>'id')::uuid;
 perform public.assessment_command(owner,t,'image-submit-hotspot','item.submit',jsonb_build_object('id',hotspot));perform public.assessment_command(reviewer,t,'image-approve-hotspot','item.approve',jsonb_build_object('id',hotspot));
 perform public.assessment_command(owner,t,'image-submit-diagram','item.submit',jsonb_build_object('id',diagram));perform public.assessment_command(reviewer,t,'image-approve-diagram','item.approve',jsonb_build_object('id',diagram));
 definition:=jsonb_build_object('schema_version','assessment.definition.v1','title','Image interaction assessment','locale','en','duration_seconds',600,'shuffle_items',false,'shuffle_options',false,'sections',jsonb_build_array(jsonb_build_object('id','20000000-0000-4000-8000-000000000001','title','Image interaction','item_version_ids',jsonb_build_array(hotspot,diagram),'draw_count',2)));
 did:=(public.assessment_command(owner,t,'image-definition','assessment.create',jsonb_build_object('definition',definition))->>'id')::uuid;
 ver:=(public.assessment_command(owner,t,'image-publish','assessment.publish',jsonb_build_object('id',did,'revision',1))->>'id')::uuid;
 win:=(public.assessment_command(owner,t,'image-window','window.create',jsonb_build_object('assessment_version_id',ver,'title','Image response sitting','opens_at',clock_timestamp()-interval '1 hour','closes_at',clock_timestamp()+interval '1 hour'))->>'id')::uuid;
 reg:=(public.assessment_command(owner,t,'image-registration','registration.create',jsonb_build_object('window_id',win,'candidate_id',candidate))->>'id')::uuid;
 form:=jsonb_build_object('schema_version','assessment.manifest.v1','assessment_version_id',ver,'duration_seconds',600,'title','Image interaction','locale','en','sections',jsonb_build_array(jsonb_build_object('id','20000000-0000-4000-8000-000000000001','title','Images','items',(select jsonb_agg(jsonb_build_object('item_version_id',v.id,'item',v.payload) order by v.id) from public.assessment_item_versions v where v.id in(hotspot,diagram)))));
 if form::text~'"(hotspot|regions|correct)"\s*:' then raise exception 'Private scoring targets or answers leaked into public form';end if;
 aid:=(public.assessment_command(candidate,t,'image-start','attempt.start',jsonb_build_object('registration_id',reg,'manifest',form,'manifest_hash',repeat('f',64)))->>'id')::uuid;
 data:=jsonb_build_object('attempt_id',aid,'sequence',1,'item_version_id',hotspot,'response',jsonb_build_object('schema_version','assessment.image-point.v1','x',.2,'y',.3),'payload_hash',repeat('a',64));
 begin perform pg_temp.assessment_command(candidate,t,'image-spoofed-score','response.append',jsonb_set(data,'{response,score}','1'));raise exception 'Point response contained caller score';exception when check_violation then null;end;
 begin perform pg_temp.assessment_command(candidate,t,'image-out-of-range','response.append',jsonb_set(data,'{response,x}','1.01'));raise exception 'Out-of-range point saved';exception when check_violation then null;end;
 reply:=pg_temp.assessment_command(candidate,t,'image-hotspot-response','response.append',data);
 if pg_temp.assessment_command(candidate,t,'image-hotspot-response','response.append',data)<>reply then raise exception 'Image point receipt changed on retry';end if;
 data:=jsonb_build_object('attempt_id',aid,'sequence',2,'item_version_id',diagram,'response','{"label_1":"feline"}'::jsonb,'payload_hash',repeat('b',64));
 begin perform pg_temp.assessment_command(candidate,t,'image-unknown-label','response.append',jsonb_set(data,'{response,foreign_label}','"answer"'));raise exception 'Foreign diagram label saved';exception when check_violation then null;end;
 perform pg_temp.assessment_command(candidate,t,'image-diagram-response','response.append',data);
 if (select last_sequence from public.assessment_attempts where id=aid)<>2 or (select count(*) from public.assessment_response_journal where attempt_id=aid)<>2 then raise exception 'Invalid/replayed image responses advanced canonical sequence';end if;
 perform pg_temp.assessment_command(candidate,t,'image-submit-attempt','attempt.submit',jsonb_build_object('attempt_id',aid));
 if (public.assessment_grading_input(t,aid,1)->'items')::text not like '%regions%' or not exists(select 1 from public.assessment_grading_jobs where attempt_id=aid and generation=1) then raise exception 'Private grading bundle lost image keys or finalization job';end if;
 if has_function_privilege('authenticated','assessment_image_region_valid(jsonb)','execute') or has_table_privilege('authenticated','assessment_item_keys','select') then raise exception 'Private image scoring authority leaked';end if;
end;$$;
rollback;
